-- -----------------------------------
-- Table structure for `sites_pg_update_log`
-- -----------------------------------

DROP TABLE IF EXISTS `sites_pg_update_log`;
CREATE TABLE `sites_pg_update_log` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `table_name` varchar(50) NOT NULL COMMENT 'Source table: sites, dvrsite, or dvronline',
  `record_id` int(11) NOT NULL COMMENT 'Primary key value (SN or id)',
  `operation` varchar(10) NOT NULL COMMENT 'INSERT or UPDATE',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1=pending, 2=completed, 3=failed',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `error_message` text,
  `retry_count` int(11) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_status_created` (`status`,`created_at`),
  KEY `idx_table_record` (`table_name`,`record_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=2622 DEFAULT CHARSET=utf8mb4 COMMENT='Tracks sites/dvrsite/dvronline changes for PostgreSQL sync';

